#  在线更新 (GitHub Releases)
# ============================================================

def _parse_version(s: str):
    """'v1.2.3' / '1.2.3' -> (1, 2, 3)。非数字段按 0 处理。"""
    s = (s or "").strip().lstrip("vV")
    parts = []
    for seg in s.split("."):
        num = ""
        for ch in seg:
            if ch.isdigit():
                num += ch
            else:
                break
        parts.append(int(num) if num else 0)
    # 1.2 和 1.2.0 表示同一版本，避免两段版本号误判更新。
    while len(parts) > 1 and parts[-1] == 0:
        parts.pop()
    return tuple(parts) if parts else (0,)


def _is_newer(remote: str, local: str) -> bool:
    return _parse_version(remote) > _parse_version(local)


def _plain_notes(text: str) -> str:
    """把 release 说明里的 markdown 标记清成干净纯文本(弹窗不渲染 markdown)。"""
    out = []
    for raw in (text or "").splitlines():
        line = raw.rstrip()
        line = re.sub(r"^\s{0,3}#{1,6}\s*", "", line)        # 标题 ##
        line = re.sub(r"^(\s*)[-*+]\s+", r"\1• ", line)      # 无序列表 - * +
        line = re.sub(r"^(\s*)>\s?", r"\1", line)            # 引用 >
        line = re.sub(r"\*\*(.+?)\*\*", r"\1", line)         # 粗体 **x**
        line = re.sub(r"(?<!\*)\*(?!\*)(.+?)\*", r"\1", line)  # 斜体 *x*
        line = re.sub(r"`([^`]+)`", r"\1", line)             # 行内代码 `x`
        out.append(line)
    # 折叠多余空行
    cleaned = re.sub(r"\n{3,}", "\n\n", "\n".join(out)).strip()
    return cleaned


def _ssl_context():
    """打包后的 Python 没有系统 CA 证书库, HTTPS 校验会因找不到根证书而失败。
    用 certifi 自带的 CA 包构建 SSL 上下文; 没有 certifi 时退回默认。"""
    try:
        import ssl
        import certifi
        return ssl.create_default_context(cafile=certifi.where())
    except Exception:
        try:
            import ssl
            return ssl.create_default_context()
        except Exception:
            return None


def fetch_latest_release(timeout=10):
    """读取仓库 version.json(经 raw CDN, 不受 GitHub API 限流), 返回更新信息。

    version.json 形如:
      {"version":"1.1.3","notes":"...","assets":{"darwin":"BitFerry-macos-arm64.zip",
       "windows":"BitFerry-windows-x64.exe"}}
    下载直链由 release 资产地址拼出: .../releases/download/v<version>/<asset>。
    """
    import urllib.request
    req = urllib.request.Request(
        GITHUB_VERSION_JSON,
        headers={"User-Agent": f"BitFerry/{__version__}",
                 "Cache-Control": "no-cache"})
    with urllib.request.urlopen(req, timeout=timeout, context=_ssl_context()) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    version = (data.get("version", "") or "").lstrip("vV")
    assets = data.get("assets", {}) or {}
    sysname = platform.system()
    key = "darwin" if sysname == "Darwin" else ("windows" if sysname == "Windows" else "")
    name = assets.get(key)
    asset = None
    if name and version:
        asset = {"name": name, "size": 0,
                 "url": f"{GITHUB_DL_BASE}/v{version}/{name}"}
    return {
        "version": version,
        "tag": f"v{version}" if version else "",
        "notes": data.get("notes", "") or "",
        "page": GITHUB_RELEASES_PAGE,
        "asset": asset,
    }


class UpdateSignals(QObject):
    available = pyqtSignal(object)   # 有新版: release dict
    uptodate = pyqtSignal()          # 已是最新
    failed = pyqtSignal(str)         # 检查出错


class _DLSignals(QObject):
    progress = pyqtSignal(int, int)  # (已下载字节, 总字节)
    finished = pyqtSignal()
    failed = pyqtSignal(str)


def check_for_update_async(signals: UpdateSignals):
    """后台线程检查更新，结果通过 signals 回主线程。"""
    def worker():
        try:
            rel = fetch_latest_release()
            if rel["version"] and _is_newer(rel["version"], __version__):
                signals.available.emit(rel)
            else:
                signals.uptodate.emit()
        except Exception as e:
            signals.failed.emit(str(e))
    threading.Thread(target=worker, daemon=True).start()


def _download_with_progress(url, dest_path, expected_size,
                            progress_cb=None, cancel_cb=None):
    """下载到 dest_path。一期仅校验文件大小完整性。返回 True 成功 / False 取消。"""
    import urllib.request
    req = urllib.request.Request(
        url, headers={"User-Agent": f"BitFerry/{__version__}"})
    with urllib.request.urlopen(req, timeout=30, context=_ssl_context()) as resp, \
            open(dest_path, "wb") as f:
        total = expected_size or int(resp.headers.get("Content-Length", 0) or 0)
        downloaded = 0
        while True:
            if cancel_cb and cancel_cb():
                return False
            chunk = resp.read(64 * 1024)
            if not chunk:
                break
            f.write(chunk)
            downloaded += len(chunk)
            if progress_cb:
                progress_cb(downloaded, total)
    actual = dest_path.stat().st_size
    if expected_size and actual != expected_size:
        raise IOError(f"下载文件大小不符: 期望 {expected_size}, 实际 {actual}")
    return True


def _current_app_bundle():
    """macOS: 返回正在运行的 .app 路径 (Path)，找不到返回 None。"""
    for p in Path(sys.executable).parents:
        if p.suffix == ".app":
            return p
    return None


def _extract_macos_update(zip_path, workdir):
    """ditto 保留 .app 的执行权限和框架符号链接，zipfile.extractall 不保留。"""
    import zipfile
    with zipfile.ZipFile(zip_path) as archive:
        for entry in archive.infolist():
            path = Path(entry.filename)
            if path.is_absolute() or ".." in path.parts:
                raise ValueError("更新包包含越界路径")
    subprocess.run(["/usr/bin/ditto", "-x", "-k", str(zip_path), str(workdir)],
                   check=True, capture_output=True)


def apply_update_macos(zip_path):
    """解压新包并安排"退出后替换+重启"，调用后应立即退出当前进程。"""
    import shlex
    app = _current_app_bundle()
    if app is None:
        raise RuntimeError("未找到当前 .app，可能不是打包运行。")
    workdir = Path(tempfile.mkdtemp(prefix="bitferry_update_"))
    _extract_macos_update(zip_path, workdir)
    new_app = next((c for c in workdir.iterdir() if c.suffix == ".app"), None)
    if new_app is None:
        new_app = next(iter(workdir.rglob("*.app")), None)
    if new_app is None:
        raise RuntimeError("更新包内未找到 .app")
    executable = new_app / "Contents" / "MacOS" / "BitFerry"
    if not executable.is_file() or not os.access(executable, os.X_OK):
        raise RuntimeError("更新包主程序缺失或没有执行权限，已保留当前版本。")

    pid = os.getpid()
    backup = app.with_name(app.name + ".bak")
    script = workdir / "apply_update.sh"
    # 注意: 不重新签名——发布包已用稳定自签证书签好名，重签会改变签名标识、
    # 导致 macOS 截图(屏幕录制)的 TCC 授权失效。
    script.write_text(f'''#!/bin/bash
while kill -0 {pid} 2>/dev/null; do sleep 0.3; done
sleep 0.5
TARGET={shlex.quote(str(app))}
NEW={shlex.quote(str(new_app))}
BACKUP={shlex.quote(str(backup))}
rm -rf "$BACKUP" 2>/dev/null || true
mv "$TARGET" "$BACKUP" || exit 1
if mv "$NEW" "$TARGET"; then
    xattr -dr com.apple.quarantine "$TARGET" 2>/dev/null || true
    if open "$TARGET"; then
        rm -rf "$BACKUP" 2>/dev/null || true
    else
        rm -rf "$TARGET"
        mv "$BACKUP" "$TARGET"
        open "$TARGET"
    fi
else
    mv "$BACKUP" "$TARGET" 2>/dev/null || true
    open "$TARGET"
fi
rm -rf {shlex.quote(str(workdir))} 2>/dev/null || true
''', encoding="utf-8")
    script.chmod(0o755)
    subprocess.Popen(["/bin/bash", str(script)],
                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                     start_new_session=True)


def apply_update_windows(new_exe_path):
    """覆盖当前 exe 并重启，调用后应立即退出当前进程。"""
    cur = Path(sys.executable)
    pid = os.getpid()          # 子进程(Python 运行所在)
    ppid = os.getppid()        # onefile 引导器(父进程): 锁着 exe 文件、拥有 _MEI 解包目录
    workdir = Path(new_exe_path).parent
    bat = workdir / "apply_update.bat"
    log = workdir / "apply_update.log"
    # 关键: onefile exe 同时有引导器(父)和子进程两个进程, 两者都锁着 exe 文件、
    # 父进程还拥有 _MEI 临时解包目录。必须等"父+子都退出"才能覆盖, 否则在父进程
    # 仍存活时替换 exe, 会损坏其正在运行的映像, 重启时报 "Failed to load Python DLL
    # (_MEI...\pythonXXX.dll)"。这里等两个 PID 都消失、再留出落地时间后才覆盖+重启。
    bat.write_text(
        "@echo off\r\n"
        "setlocal\r\n"
        f'set "SRC={new_exe_path}"\r\n'
        f'set "DST={cur}"\r\n'
        f'set "LOG={log}"\r\n'
        f'echo [%date% %time%] waiting for pids {pid} {ppid} > "%LOG%"\r\n'
        "set /a waited=0\r\n"
        ":waitloop\r\n"
        'set "alive="\r\n'
        f'tasklist /FI "PID eq {pid}" /NH 2>NUL | find "{pid}" >NUL && set alive=1\r\n'
        f'tasklist /FI "PID eq {ppid}" /NH 2>NUL | find "{ppid}" >NUL && set alive=1\r\n'
        "if not defined alive goto gone\r\n"
        "set /a waited+=1\r\n"
        # 兜底: 子进程迟迟不退出时强制结束, 避免无限等待(父引导器随后会自行退出)
        f'if %waited% geq 20 taskkill /PID {pid} /F >NUL 2>&1\r\n'
        "ping -n 2 127.0.0.1 >NUL\r\n"
        "goto waitloop\r\n"
        ":gone\r\n"
        # 留出时间让 OS 彻底释放 exe 文件锁、引导器清理完 _MEI
        "ping -n 3 127.0.0.1 >NUL\r\n"
        "set /a tries=0\r\n"
        ":copyloop\r\n"
        'copy /Y "%SRC%" "%DST%" >> "%LOG%" 2>&1\r\n'
        "if not errorlevel 1 goto copied\r\n"
        "set /a tries+=1\r\n"
        "if %tries% lss 20 (ping -n 2 127.0.0.1 >NUL & goto copyloop)\r\n"
        'echo [%date% %time%] copy failed after %tries% tries >> "%LOG%"\r\n'
        "goto launch\r\n"
        ":copied\r\n"
        # 关键: 刚覆盖出来的是未签名新 exe, Windows Defender 会立即扫描并独占锁定它。
        # 若此时就启动, onefile 引导器解包不出 pythonXXX.dll, 会弹 "Failed to load
        # Python DLL"。这里轮询到该文件可被独占打开(扫描放锁)后再启动, 比盲等更稳。
        'echo [%date% %time%] copied, waiting for AV/file lock to clear >> "%LOG%"\r\n'
        "set /a lk=0\r\n"
        ":lockwait\r\n"
        '(call ) 9>>"%DST%" 2>NUL && goto warm\r\n'
        "set /a lk+=1\r\n"
        'if %lk% geq 40 (echo [%date% %time%] still locked, continuing >> "%LOG%" & goto warm)\r\n'
        "ping -n 2 127.0.0.1 >NUL\r\n"
        "goto lockwait\r\n"
        ":warm\r\n"
        # 仅文件写锁释放还不够: 新 exe 是未签名文件, 启动时 Defender 会做"执行时扫描",
        # 它会打断 onefile 引导器解包, 导致 pythonXXX.dll 加载失败。这里先整文件读取
        # 一遍(certutil 计算哈希), 强制杀软完成内容扫描并缓存结论; 之后再启动时走缓存,
        # 不再触发会打断解包的扫描。
        'echo [%date% %time%] warming AV scan cache >> "%LOG%"\r\n'
        'certutil -hashfile "%DST%" SHA256 >> "%LOG%" 2>&1\r\n'
        "ping -n 3 127.0.0.1 >NUL\r\n"
        ":launch\r\n"
        'echo [%date% %time%] launching >> "%LOG%"\r\n'
        'start "" "%DST%"\r\n'
        'del "%~f0"\r\n',
        encoding="utf-8")
    # 只用 CREATE_NO_WINDOW: 它单独即可让 cmd 无窗口运行; 再叠加 DETACHED_PROCESS
    # 会与之冲突, 反而弹出可见的命令行窗口。父进程退出后该 cmd 仍会继续执行。
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    subprocess.Popen(["cmd", "/c", str(bat)], creationflags=flags)


_SINGLE_INSTANCE_KEY = "BitFerry-single-instance"


def _windows_mutex_api():
    import ctypes
    from ctypes import wintypes
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel.CreateMutexW.argtypes = [ctypes.c_void_p, wintypes.BOOL, wintypes.LPCWSTR]
    kernel.CreateMutexW.restype = wintypes.HANDLE
    kernel.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel.CloseHandle.restype = wintypes.BOOL
    return kernel, ctypes.get_last_error


class _SingleInstanceGuard:
    """锁决定是否能启动；本地管道仅负责唤起窗口，不能替代互斥锁。"""
    def __init__(self):
        self._handle = None
        self._kernel = None
        self._lock_file = None

    def acquire(self):
        if platform.system() == "Windows":
            kernel, get_error = _windows_mutex_api()
            # 接收端口是全机资源，同一台机器的多个登录会话也不能抢占。
            handle = kernel.CreateMutexW(None, False, "Global\\BitFerry-single-instance")
            error = get_error()
            if not handle:
                raise RuntimeError(f"无法建立单实例保护（Windows 错误 {error}）。"
                                   "程序可能已在其他账户或不同权限下运行。")
            if error == 183:  # ERROR_ALREADY_EXISTS；不能把打开已有句柄当成获锁
                kernel.CloseHandle(handle)
                return False
            self._kernel, self._handle = kernel, handle
            return True
        APP_DATA.mkdir(parents=True, exist_ok=True)
        lock = QLockFile(str(APP_DATA / "instance.lock"))
        lock.setStaleLockTime(0)  # 长期持有，不按文件年龄抢走活跃实例的锁
        if not lock.tryLock(0):
            if lock.error() != QLockFile.LockError.LockFailedError:
                raise RuntimeError("无法建立单实例保护，请检查应用数据目录的权限。")
            return False
        self._lock_file = lock
        return True

    def release(self):
        if self._handle is not None:
            self._kernel.CloseHandle(self._handle)
            self._handle = None
        if self._lock_file is not None:
            self._lock_file.unlock()
            self._lock_file = None


def _activate_existing_instance(timeout_ms=4000):
    """返回 (已连接, 已响应)。等待首次启动完成，但绝不另开一套服务。"""
    deadline = time.monotonic() + timeout_ms / 1000
    while time.monotonic() < deadline:
        probe = QLocalSocket()
        try:
            probe.connectToServer(_SINGLE_INSTANCE_KEY)
            remaining = max(1, int((deadline - time.monotonic()) * 1000))
            if probe.waitForConnected(min(200, remaining)):
                probe.write(b"raise")
                probe.flush()
                remaining = max(1, int((deadline - time.monotonic()) * 1000))
                probe.waitForBytesWritten(min(200, remaining))
                reply = bytes(probe.readAll())
                while b"raised" not in reply and time.monotonic() < deadline:
                    remaining = max(1, int((deadline - time.monotonic()) * 1000))
                    if not probe.waitForReadyRead(remaining):
                        break
                    reply += bytes(probe.readAll())
                return True, b"raised" in reply
        finally:
            probe.abort()
        time.sleep(0.05)
    return False, False


def main():
    app = QApplication(sys.argv)
    app.setApplicationName("BitFerry")
    guard = _SingleInstanceGuard()
    try:
        acquired = guard.acquire()
    except Exception as e:
        QMessageBox.warning(None, "BitFerry 无法启动", str(e))
        return
    if not acquired:
        _, activated = _activate_existing_instance()
        if not activated:
            QMessageBox.information(None, "BitFerry 已在运行",
                                    "已有实例正在启动、暂未响应，或运行于其他账户。\n"
                                    "请稍后重试或检查任务栏、系统托盘；不会启动第二个实例。")
        return

    try:
        # 兼容升级前已经运行的旧版本：它还没有互斥锁，但可能拥有唤起管道。
        connected, activated = _activate_existing_instance(timeout_ms=200)
        if connected:
            if not activated:
                QMessageBox.information(None, "BitFerry 已在运行", "已请求现有实例显示窗口，请检查任务栏或系统托盘。")
            return
        # 只有持锁实例可以处理崩溃残留的本地服务。
        QLocalServer.removeServer(_SINGLE_INSTANCE_KEY)
        server = QLocalServer()
        if not server.listen(_SINGLE_INSTANCE_KEY):
            QMessageBox.warning(None, "BitFerry 无法启动",
                                f"无法创建窗口唤起服务：{server.errorString()}")
            return

        _try_open_win_firewall()
        # Windows 区域可能启用本地数字（如 zh-Hans-MO 的〇一二…），Qt 会把字号、
        # 进度百分比显示成〡〨；按语言/文字/地区重建区域，保留习惯但统一用 0-9。
        sys_locale = QLocale.system()
        QLocale.setDefault(QLocale(sys_locale.language(), sys_locale.script(), sys_locale.territory()))
        f = QFont()
        f.setFamily("PingFang SC" if platform.system() == "Darwin" else "Microsoft YaHei UI")
        f.setPointSize(13 if platform.system() == "Darwin" else 10)
        app.setFont(f)
        win = MainWindow()
        import traceback
        previous_hook = sys.excepthook
        def report_exception(kind, value, tb):
            win._diagnostics.record("error", "".join(traceback.format_exception(kind, value, tb)))
            previous_hook(kind, value, tb)
        sys.excepthook = report_exception
        if hasattr(threading, "excepthook"):
            threading.excepthook = lambda args: report_exception(args.exc_type, args.exc_value, args.exc_traceback)

        def _on_second_instance():
            while server.hasPendingConnections():
                conn = server.nextPendingConnection()
                if conn is not None:
                    win._bring_to_front()
                    win._append_log("重复启动：已唤起现有窗口", "info")
                    conn.write(b"raised")
                    conn.flush()
                    conn.disconnected.connect(conn.deleteLater)
                    conn.disconnectFromServer()
        server.newConnection.connect(_on_second_instance)
        win._instance_server = server
        # 初始化窗口期间已经到达的连接，也必须被处理。
        QTimer.singleShot(0, _on_second_instance)
        win.show()
        app.exec()
    finally:
        # 关监听后再释放互斥锁；不在 aboutToQuit 时提前允许第二个实例抢入。
        if "win" in locals():
            win.discovery.stop()
            win.receiver.stop()
            win.webbridge.stop()
        if "server" in locals():
            server.close()
        guard.release()


if __name__ == "__main__":
    main()
